    step = min(int(obs.get("step", 0) or 0), len(TRACE_ACTIONS) - 1)
    action = copy.deepcopy(TRACE_ACTIONS[step])
    player = int(obs.get("player", 0) or 0)
    expected_hands = len(obs["farms"][player].get("hands", []))
    actual_hands = len(action["hands"])
    if actual_hands > expected_hands:
        action["hands"] = action["hands"][:expected_hands]
    elif actual_hands < expected_hands:
        action["hands"].extend([["PASS"]] * (expected_hands - actual_hands))
    return action
